// Generated once with the official 7-Zip 26.02 PPMd encoder.
// Tests consume immutable bytes and never invoke an external executable.
const PPMD_RESTART_ARCHIVE = ''

export function ppmdRestartArchiveFixture(): Uint8Array {
  return Uint8Array.from(Buffer.from(PPMD_RESTART_ARCHIVE, 'base64'))
}

export function ppmdRestartPayload(): Uint8Array {
  const bytes = new Uint8Array(40_000)
  let state = 0x12345678
  for (let index = 0; index < bytes.length; index += 1) {
    state ^= state << 13
    state ^= state >>> 17
    state ^= state << 5
    bytes[index] = state & 0xff
  }
  return bytes
}
